package com.eduhub.edu_hub.scheduling.api.dto;

import com.eduhub.edu_hub.scheduling.api.serialization.ClassCapacityDeserializer;
import com.eduhub.edu_hub.scheduling.domain.policy.ModuleClassPolicy;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotNull;
import lombok.Data;
import tools.jackson.databind.annotation.JsonDeserialize;

@Data
public class CreateModuleClassRequest {
    @NotNull
    @Min(1)
    @Max(ModuleClassPolicy.MAX_CAPACITY)
    @JsonDeserialize(using = ClassCapacityDeserializer.class)
    private Integer maxCapacity = ModuleClassPolicy.MAX_CAPACITY;
}

package com.eduhub.edu_hub.scheduling.api.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.util.List;
import lombok.Data;

@Data
public class CreateModuleClassesRequest {
    @NotEmpty
    private List<@NotNull @Valid SubjectClassesRequest> subjects;
}

package com.eduhub.edu_hub.scheduling.api.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.util.List;
import lombok.Data;

@Data
public class SubjectClassesRequest {
    @NotNull
    @Positive
    private Long subjectId;

    private boolean confirmAdditionalClasses;

    @NotEmpty
    private List<@NotNull @Valid CreateModuleClassRequest> classes;
}

package com.eduhub.edu_hub.scheduling.api.dto;

import com.eduhub.edu_hub.scheduling.api.serialization.ClassCapacityDeserializer;
import com.eduhub.edu_hub.scheduling.domain.policy.ModuleClassPolicy;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import lombok.Data;
import tools.jackson.databind.annotation.JsonDeserialize;

@Data
public class UpdateModuleClassRequest {
    @NotNull(message = "Sức chứa không được để trống")
    @Min(1)
    @Max(ModuleClassPolicy.MAX_CAPACITY)
    @JsonDeserialize(using = ClassCapacityDeserializer.class)
    private Integer maxCapacity;

    @NotBlank(message = "Lý do cập nhật không được để trống")
    private String reason;
}

package com.eduhub.edu_hub.scheduling.api.dto;

import jakarta.validation.constraints.NotBlank;
import lombok.Data;

@Data
public class CancelModuleClassRequest {
    @NotBlank(message = "Lý do hủy lớp không được để trống")
    private String reason;
}

package com.eduhub.edu_hub.scheduling.api.dto;

import com.eduhub.edu_hub.scheduling.domain.enums.ModuleClassStatus;
import jakarta.validation.constraints.*;
import lombok.Data;

@Data
public class ModuleClassSearchRequest {
    private String keyword;

    @Positive
    private Long semesterId;

    @Positive
    private Long subjectId;

    @Positive
    private Long lecturerId;

    private ModuleClassStatus status;

    @Min(0)
    private int page = 0;

    @Min(1)
    private int size = 20;
}

package com.eduhub.edu_hub.scheduling.api.dto;

import com.eduhub.edu_hub.scheduling.domain.enums.ModuleClassStatus;
import java.util.List;
import lombok.Builder;
import lombok.Data;

@Data
@Builder
public class ModuleClassResponse {
    private Long id;
    private Long semesterId;
    private Long subjectId;
    private Long lecturerId;
    private int classSequence;
    private String dataSource;
    private String moduleClassCode;
    private String subjectCode;
    private String subjectName;
    private int credits;
    private String lecturerName;
    private String semesterCode;
    private int maxCapacity;
    private int currentSize;
    private ModuleClassStatus status; // UNSCHEDULED, SCHEDULED, OPEN, CANCELLED
    private List<ClassScheduleResponse> schedules;
}

package com.eduhub.edu_hub.scheduling.api.dto;

import lombok.*;

@Data
@Builder
public class OpeningSubjectResponse {
    private Long subjectId;
    private String subjectCode;
    private String subjectName;
    private int credits;
    private int onTimeStudentCount;
    private int retakeStudentCount;
    private int missedStudentCount;
    private int expectedStudentCount;
    private int recommendedClassCount;
    private long existingClassCount;
    private String dataSource;
    private boolean historyComplete;
}
